def _local_refine(centers, iters=6, step=0.03):
    """Lightweight local search: perturb each center in 8 directions,
    keep the perturbation if the LP-optimal sum of radii increases."""
    centers = centers.copy()
    cur = _sum_radii(centers)
    for it in range(iters):
        improved = False
        for i in range(len(centers)):
            x, y = centers[i]
            best = (x, y)
            best_val = cur
            for dx in (-step, 0.0, step):
                for dy in (-step, 0.0, step):
                    if dx == 0.0 and dy == 0.0:
                        continue
                    nx, ny = x + dx, y + dy
                    if nx < 0.02 or nx > 0.98 or ny < 0.02 or ny > 0.98:
                        continue
                    trial = centers.copy()
                    trial[i] = [nx, ny]
                    val = _sum_radii(trial)
                    if val > best_val + 1e-9:
                        best_val = val
                        best = (nx, ny)
            if best != (x, y):
                centers[i] = best
                cur = best_val
                improved = True
        if not improved:
            break
    return centers

